    48	/** Find main session files and their subagent transcripts in a Claude Code project folder. */
    49	export function discoverSessionFiles(originDir: string): SessionFile[] {
    50	  if (!fs.existsSync(originDir)) return [];
    51	  const out: SessionFile[] = [];
    52	  for (const entry of fs.readdirSync(originDir, { withFileTypes: true })) {
    53	    if (!entry.isFile() || !entry.name.endsWith(".jsonl")) continue;
    54	    const session = entry.name.slice(0, -".jsonl".length);
    55	    if (!UUID_RE.test(session)) continue;
    56	    out.push({ session, file: path.join(originDir, entry.name), rel: entry.name, role: "main" });
    57	    const subDir = path.join(originDir, session, "subagents");
    58	    if (fs.existsSync(subDir)) {
    59	      for (const sub of fs.readdirSync(subDir)) {
    60	        if (!sub.endsWith(".jsonl")) continue;
    61	        const agentId = sub.replace(/^agent-/, "").replace(/\.jsonl$/, "");
    62	        const metaFile = path.join(subDir, sub.replace(/\.jsonl$/, ".meta.json"));
    63	        out.push({
    64	          session,
    65	          file: path.join(subDir, sub),
    66	          rel: path.join(session, "subagents", sub),
    67	          role: "subagent",
    68	          agentId,
    69	          metaFile: fs.existsSync(metaFile) ? metaFile : undefined,
    70	        });
    71	      }
    72	    }
    73	  }
    74	  return out.sort((a, b) => a.rel.localeCompare(b.rel));
    75	}
