    91	/** Read complete lines starting at a byte offset. A trailing partial line is left for the next call. */
    92	export function readNewLines(file: string, fromByte: number, fromLine: number): LineChunk {
    93	  const size = fs.statSync(file).size;
    94	  if (size <= fromByte) return { lines: [], bytes: fromByte };
    95	  const fd = fs.openSync(file, "r");
    96	  try {
    97	    const buf = Buffer.alloc(size - fromByte);
    98	    fs.readSync(fd, buf, 0, buf.length, fromByte);
    99	    const lastNl = buf.lastIndexOf(0x0a);
   100	    if (lastNl < 0) return { lines: [], bytes: fromByte };
   101	    const complete = buf.subarray(0, lastNl + 1).toString("utf8");
   102	    const lines: { text: string; line: number }[] = [];
   103	    let n = fromLine;
   104	    for (const raw of complete.split("\n")) {
   105	      if (raw === "") continue;
   106	      n++;
   107	      lines.push({ text: raw, line: n });
   108	    }
   109	    return { lines, bytes: fromByte + lastNl + 1 };
   110	  } finally {
   111	    fs.closeSync(fd);
   112	  }
   113	}
