   450	/** Apply a string transform to every string inside a JSON-like value. */
   451	export function mapStrings<T>(value: T, fn: (s: string) => string): T {
   452	  if (typeof value === "string") return fn(value) as unknown as T;
   453	  if (Array.isArray(value)) return value.map((v) => mapStrings(v, fn)) as unknown as T;
   454	  if (value && typeof value === "object") {
   455	    const out: Record<string, unknown> = {};
   456	    for (const [k, v] of Object.entries(value as Record<string, unknown>)) out[k] = mapStrings(v, fn);
   457	    return out as T;
   458	  }
   459	  return value;
   460	}
