     5	/**
     6	 * Every 10 minutes: often enough that `git status` stays mostly clean, rare enough that the
     7	 * history gets a handful of commits per hour, not one per turn. Ticks with no change commit nothing.
     8	 */
     9	export const AUTO_COMMIT_INTERVAL_MS = 10 * 60_000;
    10	
    11	export interface AutoCommitStatus {
    12	  enabled: boolean;
    13	  intervalMs: number;
    14	  lastCommit?: { ts: string; sha: string; files: number };
    15	  lastCheck?: string;
    16	  /** When the next check runs, while enabled. */
    17	  next?: string;
    18	  /** Why the last tick did not commit (no repo, merge in progress, git error). */
    19	  skipped?: string;
    20	}
    21	
    22	function git(cwd: string, args: string[]): Promise<string> {
    23	  return new Promise((resolve, reject) =>
    24	    execFile("git", args, { cwd, timeout: 30_000, maxBuffer: 16 * 1024 * 1024 }, (err, stdout, stderr) =>
    25	      err ? reject(new Error((stderr || err.message).trim())) : resolve(stdout),
    26	    ),
    27	  );
    28	}
