    30	/**
    31	 * Opt-in auto-commit of the project's .yolo-twice folder. Lives only in engine memory: it is off
    32	 * whenever the engine starts. Commits with `--only`, so whatever the user has staged stays staged
    33	 * and out of the commit.
    34	 */
    35	export class AutoCommitter {
    36	  private timer: NodeJS.Timeout | undefined;
    37	  private busy = false;
    38	  private status: AutoCommitStatus = { enabled: false, intervalMs: AUTO_COMMIT_INTERVAL_MS };
    39	
    40	  constructor(
    41	    private readonly root: string,
    42	    private readonly dir: string,
    43	    private readonly onChange: (s: AutoCommitStatus) => void,
    44	    private readonly log: (msg: string) => void,
    45	    intervalMs = AUTO_COMMIT_INTERVAL_MS,
    46	  ) {
    47	    this.status.intervalMs = intervalMs;
    48	  }
    49	
    50	  get(): AutoCommitStatus {
    51	    return { ...this.status };
    52	  }
    53	
    54	  /** Turning it on commits right away, then on every interval. */
    55	  set(enabled: boolean): AutoCommitStatus {
    56	    clearInterval(this.timer);
    57	    this.timer = undefined;
    58	    this.status = { ...this.status, enabled, skipped: undefined, next: enabled ? this.nextAt() : undefined };
    59	    if (enabled) {
    60	      this.timer = setInterval(() => {
    61	        this.status = { ...this.status, next: this.nextAt() };
    62	        void this.tick();
    63	      }, this.status.intervalMs);
    64	      this.timer.unref();
    65	      void this.tick();
    66	    }
    67	    this.onChange(this.get());
    68	    return this.get();
    69	  }
    70	
    71	  private nextAt(): string {
    72	    return new Date(Date.now() + this.status.intervalMs).toISOString();
    73	  }
    74	
    75	  stop(): void {
    76	    clearInterval(this.timer);
    77	    this.timer = undefined;
    78	  }
    79	
    80	  /** One commit attempt. Exposed for tests. */
    81	  async tick(): Promise<void> {
    82	    if (this.busy || !this.status.enabled) return;
    83	    this.busy = true;
    84	    try {
    85	      const skipped = await this.commit();
    86	      this.status = { ...this.status, lastCheck: new Date().toISOString(), skipped };
    87	      if (skipped) this.log(`auto-commit skipped: ${skipped}`);
    88	    } catch (e) {
    89	      this.status = { ...this.status, lastCheck: new Date().toISOString(), skipped: (e as Error).message };
    90	      this.log(`auto-commit failed: ${(e as Error).message}`);
    91	    } finally {
    92	      this.busy = false;
    93	    }
    94	    this.onChange(this.get());
    95	  }
    96	
    97	  /** Returns why nothing was committed, or undefined when it committed or there was nothing to do. */
    98	  private async commit(): Promise<string | undefined> {
    99	    const top = (await git(this.root, ["rev-parse", "--show-toplevel"]).catch(() => "")).trim();
   100	    if (!top) return "not a git repository";
   101	    // never interfere with a merge, rebase, cherry-pick or another git process
   102	    for (const p of ["index.lock", "MERGE_HEAD", "REBASE_HEAD", "CHERRY_PICK_HEAD", "rebase-merge", "rebase-apply"]) {
   103	      const abs = path.resolve(this.root, (await git(this.root, ["rev-parse", "--git-path", p])).trim());
   104	      if (fs.existsSync(abs)) return `git busy (${p})`;
   105	    }
   106	    if (!(await git(this.root, ["symbolic-ref", "-q", "HEAD"]).catch(() => ""))) return "detached HEAD";
   107	    const rel = path.relative(top, this.dir) || ".";
   108	    const changed = (await git(top, ["status", "--porcelain", "--untracked-files=all", "--", rel])).split("\n").filter(Boolean);
   109	    if (changed.length === 0) return undefined;
   110	    await git(top, ["add", "-A", "--", rel]);
   111	    // --only commits just this path from the work tree; the rest of the user's index is left as it was
   112	    await git(top, ["commit", "--only", "--no-verify", "-q", "-m", `yolo-twice: auto-commit session data (${changed.length} files)`, "--", rel]);
   113	    const sha = (await git(top, ["rev-parse", "--short", "HEAD"])).trim();
   114	    this.status = { ...this.status, lastCommit: { ts: new Date().toISOString(), sha, files: changed.length } };
   115	    this.log(`auto-commit ${sha}: ${changed.length} files`);
   116	    return undefined;
   117	  }
   118	}
