   410	/**
   411	 * What Claude is doing in a session, told by Claude Code's hooks (forwarded to POST /hook):
   412	 * working between a prompt and the end of the turn, waiting while it asks you for something.
   413	 * Without hooks there is no activity, and the UI says nothing rather than guessing.
   414	 */
   415	
   416	export type Activity = "working" | "waiting" | "idle";
   417	
   418	export interface HookPayload {
   419	  hook_event_name?: string;
   420	  /** Notification: permission_prompt, idle_prompt, elicitation_dialog, auth_success… */
   421	  notification_type?: string;
   422	  /** PreCompact / PostCompact: manual (/compact) or auto (mid-turn). */
   423	  trigger?: string;
   424	}
   425	
   426	/** The activity a hook implies, or undefined when it says nothing about it. */
   427	export function activityFrom(hook: HookPayload): Activity | undefined {
   428	  switch (hook.hook_event_name) {
   429	    case "UserPromptSubmit":
   430	    case "PreToolUse":
   431	    case "PostToolUse":
   432	    case "SubagentStart":
   433	    case "SubagentStop":
   434	      return "working";
   435	    case "PreCompact":
   436	      return "working";
   437	    case "PostCompact":
   438	      // a /compact you ran ends idle; an automatic one happens mid-turn and the turn goes on
   439	      return hook.trigger === "manual" ? "idle" : "working";
   440	    case "Notification":
   441	      // "idle_prompt" is the reminder that Claude is done and waiting for your next prompt
   442	      return hook.notification_type === "idle_prompt" || hook.notification_type === "auth_success" ? "idle" : "waiting";
   443	    case "Stop":
   444	    case "SessionStart":
   445	    case "SessionEnd":
   446	      return "idle";
   447	    default:
   448	      return undefined;
   449	  }
   450	}

