  schedule(reason: string, session?: string): void {
    clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      try {
        this.ingest(session);
      } catch (e) {
        this.log(`ingest failed (${reason}): ${(e as Error).message}`);
      }
    }, 300);
